final class mediademuxer_s extends ffi.Opaque {}

/// @brief Enumeration for media demuxer state.
/// @since_tizen 3.0
abstract class mediademuxer_state {
  /// < The mediademuxer is not created
  static const int MEDIADEMUXER_STATE_NONE = 0;

  /// < The mediademuxer is created, but not prepared
  static const int MEDIADEMUXER_STATE_IDLE = 1;

  /// < The mediademuxer is ready to demux media
  static const int MEDIADEMUXER_STATE_READY = 2;

  /// < The mediademuxer is demuxing media
  static const int MEDIADEMUXER_STATE_DEMUXING = 3;
}

/// @brief Enumeration for media demuxer error.
/// @since_tizen 3.0
abstract class mediademuxer_error_e {
  /// < Successful
  static const int MEDIADEMUXER_ERROR_NONE = 0;

  /// < Out of memory
  static const int MEDIADEMUXER_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int MEDIADEMUXER_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid operation
  static const int MEDIADEMUXER_ERROR_INVALID_OPERATION = -38;

  /// < Not supported
  static const int MEDIADEMUXER_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Permission denied
  static const int MEDIADEMUXER_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid state
  static const int MEDIADEMUXER_ERROR_INVALID_STATE = -27131903;

  /// < Invalid path
  static const int MEDIADEMUXER_ERROR_INVALID_PATH = -27131902;

  /// < Resource limit
  static const int MEDIADEMUXER_ERROR_RESOURCE_LIMIT = -27131901;

  /// < Seek operation failure
  static const int MEDIADEMUXER_ERROR_SEEK_FAILED = -27131900;

  /// < Not permitted format
  static const int MEDIADEMUXER_ERROR_DRM_NOT_PERMITTED = -27131899;
}

